=<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Favour — Knowledge Upload</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  :root {
    --bg: #0f0f0f; --surface: #1a1a1a; --border: #2a2a2a;
    --border-focus: #f97316; --accent: #f97316; --accent-dim: rgba(249,115,22,0.12);
    --text: #f5f5f5; --text-muted: #888;
    --success-bg: #0f2a1a; --success-border: #16a34a; --success-text: #4ade80;
    --error-bg: #2a0f0f; --error-border: #dc2626; --error-text: #f87171;
    --radius: 10px; --font: 'Inter', system-ui, sans-serif;
  }
  @import url('[URL]');
  body { background: var(--bg); color: var(--text); font-family: var(--font); min-height: 100vh; display: flex; align-items: center; justify-content: center; padding: 2rem 1rem; }
  .card { background: var(--surface); border: 1px solid var(--border); border-radius: 16px; width: 100%; max-width: 480px; padding: 2.5rem 2rem; }
  .brand { display: flex; align-items: center; gap: 10px; margin-bottom: 2rem; }
  .brand-dot { width: 10px; height: 10px; background: var(--accent); border-radius: 50%; }
  .brand-name { font-size: 13px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--text-muted); }
  h1 { font-size: 22px; font-weight: 600; color: var(--text); margin-bottom: 6px; line-height: 1.3; }
  .subtitle { font-size: 14px; color: var(--text-muted); margin-bottom: 2rem; line-height: 1.6; }
  .field { margin-bottom: 1.25rem; }
  label { display: block; font-size: 13px; font-weight: 500; color: var(--text-muted); margin-bottom: 6px; letter-spacing: 0.02em; }
  select { width: 100%; background: var(--bg); border: 1px solid var(--border); border-radius: var(--radius); color: var(--text); font-family: var(--font); font-size: 14px; padding: 11px 14px; appearance: none; background-image: url("data:image/svg+xml,%3Csvg xmlns='[URL]' width='12' height='12' viewBox='0 0 12 12'%3E%3Cpath fill='%23888' d='M6 8L1 3h10z'/%3E%3C/svg%3E"); background-repeat: no-repeat; background-position: right 14px center; cursor: pointer; transition: border-color 0.15s; }
  select:focus { outline: none; border-color: var(--border-focus); box-shadow: 0 0 0 3px var(--accent-dim); }
  select option { background: #1a1a1a; }
  .drop-zone { border: 1.5px dashed var(--border); border-radius: var(--radius); padding: 2rem 1.5rem; text-align: center; cursor: pointer; transition: border-color 0.15s, background 0.15s; position: relative; }
  .drop-zone:hover, .drop-zone.dragover { border-color: var(--accent); background: var(--accent-dim); }
  .drop-zone input[type="file"] { position: absolute; inset: 0; opacity: 0; cursor: pointer; width: 100%; height: 100%; }
  .drop-icon { width: 36px; height: 36px; margin: 0 auto 10px; background: var(--accent-dim); border-radius: 8px; display: flex; align-items: center; justify-content: center; }
  .drop-icon svg { color: var(--accent); }
  .drop-label { font-size: 14px; font-weight: 500; color: var(--text); margin-bottom: 4px; }
  .drop-hint { font-size: 12px; color: var(--text-muted); }
  .file-selected { display: none; align-items: center; gap: 10px; background: var(--accent-dim); border: 1px solid var(--accent); border-radius: var(--radius); padding: 10px 14px; margin-top: 10px; }
  .file-selected.show { display: flex; }
  .file-selected-name { font-size: 13px; font-weight: 500; color: var(--accent); flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .file-remove { background: none; border: none; color: var(--text-muted); cursor: pointer; font-size: 16px; padding: 0; line-height: 1; flex-shrink: 0; }
  .file-remove:hover { color: var(--error-text); }
  .submit-btn { width: 100%; background: var(--accent); color: #fff; border: none; border-radius: var(--radius); font-family: var(--font); font-size: 14px; font-weight: 600; padding: 13px; cursor: pointer; margin-top: 1.5rem; transition: opacity 0.15s, transform 0.1s; display: flex; align-items: center; justify-content: center; gap: 8px; }
  .submit-btn:hover:not(:disabled) { opacity: 0.88; }
  .submit-btn:active:not(:disabled) { transform: scale(0.98); }
  .submit-btn:disabled { opacity: 0.4; cursor: not-allowed; }
  .spinner { width: 16px; height: 16px; border: 2px solid rgba(255,255,255,0.3); border-top-color: #fff; border-radius: 50%; animation: spin 0.7s linear infinite; display: none; }
  .submit-btn.loading .spinner { display: block; }
  .submit-btn.loading .btn-text { opacity: 0.7; }
  @keyframes spin { to { transform: rotate(360deg); } }
  .alert { display: none; border-radius: var(--radius); padding: 12px 14px; font-size: 13px; margin-top: 1rem; line-height: 1.5; }
  .alert.show { display: block; }
  .alert.success { background: var(--success-bg); border: 1px solid var(--success-border); color: var(--success-text); }
  .alert.error { background: var(--error-bg); border: 1px solid var(--error-border); color: var(--error-text); }
  .divider { border: none; border-top: 1px solid var(--border); margin: 2rem 0 1.25rem; }
  .footer-note { font-size: 12px; color: var(--text-muted); text-align: center; line-height: 1.6; }
</style>
</head>
<body>
<div class="card">
  <div class="brand"><div class="brand-dot"></div><span class="brand-name">Favour Agent</span></div>
  <h1>Upload knowledge document</h1>
  <p class="subtitle">Upload a PDF to update table_3 agent's knowledge base. The old version of this document type will be replaced automatically.</p>
  <div class="field">
    <label for="docType">Document type</label>
    <select id="docType" required>
      <option value="" disabled selected>Select a document type</option>
      <option value="a">Product List & Prices</option>
      <option value="b">Wholesaler PC Promp</option>
      <option value="c">Wholesaler Pharma Promo</option>
      <option value="d">Promo Guide</option>
    </select>
  </div>
  <div class="field">
    <label>PDF file</label>
    <div class="drop-zone" id="dropZone">
      <input type="file" id="fileInput" accept=".pdf" />
      <div class="drop-icon"><svg width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M21 15v4a2 2 0 01-2 2H5a2 2 0 01-2-2v-4M17 8l-5-5-5 5M12 3v12"/></svg></div>
      <div class="drop-label">Drop PDF here or click to browse</div>
      <div class="drop-hint">PDF files only · max 20MB</div>
    </div>
    <div class="file-selected" id="fileSelected">
      <svg width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
      <span class="file-selected-name" id="fileSelectedName"></span>
      <button class="file-remove" id="fileRemove" type="button">x</button>
    </div>
  </div>
  <button class="submit-btn" id="submitBtn" disabled>
    <div class="spinner"></div>
    <span class="btn-text">Upload document</span>
  </button>
  <div class="alert" id="alertBox"></div>
  <hr class="divider">
  <p class="footer-note">Uploading replaces any existing document of the same type. The agent will use the new version immediately after processing.</p>
</div>
<script>
  const dropZone = document.getElementById('dropZone');
  const fileInput = document.getElementById('fileInput');
  const fileSelected = document.getElementById('fileSelected');
  const fileSelectedName = document.getElementById('fileSelectedName');
  const fileRemove = document.getElementById('fileRemove');
  const submitBtn = document.getElementById('submitBtn');
  const docType = document.getElementById('docType');
  const alertBox = document.getElementById('alertBox');
  let selectedFile = null;
  function checkReady() { submitBtn.disabled = !(selectedFile && docType.value); }
  function setFile(file) {
    if (!file) return;
    if (file.type !== 'application/pdf') { showAlert('error', 'Only PDF files are supported.'); return; }
    if (file.size > 20 * 1024 * 1024) { showAlert('error', 'File is too large. Maximum size is 20MB.'); return; }
    selectedFile = file; fileSelectedName.textContent = file.name;
    fileSelected.classList.add('show'); alertBox.classList.remove('show'); checkReady();
  }
  function clearFile() { selectedFile = null; fileInput.value = ''; fileSelected.classList.remove('show'); checkReady(); }
  fileInput.addEventListener('change', e => setFile(e.target.files[0]));
  fileRemove.addEventListener('click', clearFile);
  docType.addEventListener('change', checkReady);
  dropZone.addEventListener('dragover', e => { e.preventDefault(); dropZone.classList.add('dragover'); });
  dropZone.addEventListener('dragleave', () => dropZone.classList.remove('dragover'));
  dropZone.addEventListener('drop', e => { e.preventDefault(); dropZone.classList.remove('dragover'); setFile(e.dataTransfer.files[0]); });
  function showAlert(type, message) { alertBox.className = 'alert show ' + type; alertBox.textContent = message; }
  submitBtn.addEventListener('click', async () => {
    if (!selectedFile || !docType.value) return;
    submitBtn.disabled = true; submitBtn.classList.add('loading'); alertBox.classList.remove('show');
    const safeFileName = 'type_' + docType.value + '_' + selectedFile.name.replace(/[^a-zA-Z0-9._-]/g, '_');
    const formData = new FormData();
    formData.append('file', selectedFile, safeFileName);
    formData.append('doc_type', docType.value);
    formData.append('original_name', selectedFile.name);
    try {
      const res = await fetch('/webhook/bot-ingest-upload', { method: 'POST', body: formData });
      if (res.ok) { showAlert('success', 'Document uploaded successfully. The agent will start processing it now.'); clearFile(); docType.value = ''; }
      else { const txt = await res.text(); showAlert('error', 'Upload failed: ' + (txt || res.statusText)); }
    } catch (err) { showAlert('error', 'Network error - please check your connection and try again.'); }
    submitBtn.classList.remove('loading'); checkReady();
  });
</script>
</body>
</html>

