const body = $input.first().json.body || $input.first().json;
const docType = body.doc_type || 'unknown';
const originalName = body.original_name || 'document.pdf';

// The file arrives as binary data
const binaryData = $input.first().binary;
const binaryKey = Object.keys(binaryData || {})[0];

if (!binaryKey) throw new Error('No file received in upload');

const fileInfo = binaryData[binaryKey];
const mimeType = fileInfo.mimeType || 'application/pdf';

if (!mimeType.includes('pdf')) {
  throw new Error('Only PDF files are supported. Received: ' + mimeType);
}

// Build a clean filename: type_a_filename.pdf
const safeOriginal = originalName.replace(/[^a-zA-Z0-9._-]/g, '_');
const fileName = 'type_' + docType + '_' + safeOriginal;

return [{
  json: { docType, originalName, fileName, mimeType },
  binary: { data: fileInfo }
}];

const extracted = $input.first().json;
const fileName = $('Parse Upload').first().json.fileName;
const docType = $('Parse Upload').first().json.docType;

const rawText = extracted.text || extracted.data || '';

if (!rawText || rawText.trim().length === 0) {
  throw new Error('No text extracted from table_5: ' + fileName);
}

const CHUNK_SIZE = 800;
const OVERLAP = 150;

const chunks = [];
let start = 0;
let chunkIndex = 0;

while (start < rawText.length) {
  const end = Math.min(start + CHUNK_SIZE, rawText.length);
  const chunk = rawText.slice(start, end).trim();
  if (chunk.length > 50) {
    chunks.push({
      json: {
        fileName,
        docType,
        chunkIndex,
        content: chunk,
        totalChunks: 0
      }
    });
    chunkIndex++;
  }
  start += CHUNK_SIZE - OVERLAP;
}

chunks.forEach(c => { c.json.totalChunks = chunks.length; });

if (chunks.length === 0) throw new Error('No chunks generated from: ' + fileName);

return chunks;

const documentId = $('Upsert Document Record').first().json.id;
const chunks = $('Chunk Text').all();

return chunks.map(chunk => ({
  json: {
    ...chunk.json,
    document_id: documentId
  }
}));

const embeddingResponse = $input.first().json;
const embedding = embeddingResponse.embedding?.values;

if (!embedding || !Array.isArray(embedding)) {
  throw new Error('No embedding returned from table_8: ' + JSON.stringify(embeddingResponse));
}

const chunkData = $('Attach Document ID').first().json;

return [{
  json: {
    document_id: chunkData.document_id,
    file_name: chunkData.fileName,
    chunk_index: chunkData.chunkIndex,
    content: chunkData.content,
    embedding: '[' + embedding.join(',') + ']'
  }
}];

const body = $input.first().json.body || $input.first().json;
const data = body.data || {};
const key  = data.key  || {};

if (body.event !== 'messages.upsert') return [];
if (key.fromMe) return [];
if (key.remoteJid === 'status@broadcast') return [];
if (key.remoteJid?.endsWith('@g.us')) return [];
if (key.remoteJid?.endsWith('@newsletter')) return [];

const msg = data.message || {};
if (msg.stickerMessage && !msg.conversation && !msg.extendedTextMessage) return [];

const chat_id    = key.remoteJid;
const sender_id  = key.remoteJid;
const first_name = data.pushName || 'Customer';

const text =
  msg.conversation ||
  msg.extendedTextMessage?.text ||
  '';

const message_type = (msg.conversation || msg.extendedTextMessage) ? 'text' : 'unknown';

if (message_type === 'unknown') return [];

return [{ json: {
  chat_id,
  sender_id,
  first_name,
  text,
  message_type,
  message_id: key.id,
  wa_instance: body.instance || 'favour',
  raw_message: msg
} }];

// Merge customer data from table_10 Create or Update table_11
let customer;
try { customer = $('Create Customer').first().json; } catch(e) {}
if (!customer || !customer.id) {
  try { customer = $('Update table_9').first().json; } catch(e) {}
}
if (!customer || !customer.id) {
  try { customer = $('Lookup Customer').first().json; } catch(e) {}
}

const parseData = $('Parse WA Message').first().json;
const isNewCustomer = !$('Lookup Customer').first().json?.id;

return [{ json: {
  customer_id:   customer.id,
  customer_code: customer.customer_code,
  display_name:  customer.display_name || parseData.first_name,
  message_count: customer.message_count,
  is_new:        isNewCustomer,
  chat_id:       parseData.chat_id,
  wa_instance:   parseData.wa_instance,
  text:          parseData.text,
  first_name:    parseData.first_name
} }];

const customerData  = $('Merge Customer Data').first().json;
const memoryItems   = $('Load Memory').all();
const ragItems      = $('RAG Lookup').all();
const isNew         = customerData.is_new;

const memoryMessages = memoryItems
  .map(i => i.json)
  .filter(m => m.role && m.content)
  .reverse()
  .map(m => ({ role: m.role === 'assistant' ? 'assistant' : 'user', content: m.content }));

const ragContext = ragItems
  .map(i => i.json)
  .filter(r => r.similarity > 0.3)
  .map(r => r.content)
  .join('\n\n---\n\n');

const systemPrompt = `You are Favour, Orange Group's Digital Promoter assistant on WhatsApp.
Your role is strictly to handle trade promotion enquiries for Orange Group products.

CUSTOMER INFO:
- Name: ${customerData.display_name}
- Promo Code: ${customerData.customer_code}
- First time customer: ${isNew}

BEHAVIOUR RULES:
1. Be formal but warm. Always in English.
2. On first contact ONLY: introduce yourself as "Hi, I'm Favour, your Orange Group Digital Promoter 😊\nYour promo code is ${customerData.customer_code}.\nKindly show this code to our promoter to collect your gift." — nothing else, no question, no offer to help.
3. For returning customers: respond directly without re-introducing yourself.
4. Only answer questions related to Orange Group trade promotions, products, pricing, and promos.
5. If asked anything outside this scope, politely say: "I'm only able to assist with Orange Group trade promotion enquiries. For other questions, please contact our team directly."
6. NEVER make up information. Only use the context provided below.
7. If you detect a complaint, order request, or payment dispute — end your response with the exact tag: [ESCALATE]
8. Keep responses concise and clear.

KNOWLEDGE BASE CONTEXT:
${ragContext || 'No specific context found. Provide a general helpful response within scope.'}`;

return [{ json: {
  systemPrompt,
  memoryMessages,
  customerData,
  ragContext,
  isNew
} }];

