const llmResponse = $input.first().json;
const rawReply = llmResponse.choices?.[0]?.message?.content || '';

const customerData   = $('Merge Customer Data').first().json;
const conversationId = $('Upsert Conversation').first().json.conversation_id;

const shouldEscalate = rawReply.includes('[ESCALATE]');

const positiveClosings = ['thank', 'thanks', 'thank you', 'ok thank', 'alright thank', 'noted thank', 'great thank', 'perfect'];
const userMsgLower = customerData.text.toLowerCase().trim();
const shouldSendCommunity = positiveClosings.some(w => userMsgLower.includes(w));

const cleanReply = rawReply
  .replace('[ESCALATE]', '')
  .replace('[SEND_COMMUNITY_LINK]', '')
  .trim();

const positiveWords = ['thank', 'thanks', 'thank you', 'appreciate', 'helpful', 'great', 'perfect', 'noted', 'excellent', 'wonderful', 'awesome'];
const isPositiveSentiment = positiveWords.some(w => userMsgLower.includes(w));
const skipLLMReply = shouldSendCommunity;

return [{ json: {
  raw_reply:             rawReply,
  clean_reply:           cleanReply,
  should_escalate:       shouldEscalate,
  should_send_community: shouldSendCommunity,
  is_positive_sentiment: isPositiveSentiment,
  skip_llm_reply:        skipLLMReply,
  customer_id:           customerData.customer_id,
  customer_code:         customerData.customer_code,
  display_name:          customerData.display_name,
  chat_id:               customerData.chat_id,
  wa_instance:           customerData.wa_instance,
  conversation_id:       conversationId,
  user_message:          customerData.text
} }];

