const msg = $input.first().json.message || {};

// Only process replies to messages
if (!msg.reply_to_message) return [];

const adminText    = msg.text || '';
const adminChatId  = msg.chat?.id;
const replyToText  = msg.reply_to_message?.text || '';

// Extract escalation ID from table_3 original notification text
// Format: *Escalation ID:* <uuid>
const escalationMatch = replyToText.match(/Escalation ID:\*?\s*([a-f0-9-]{36})/i);
if (!escalationMatch) return [];

const escalationId = escalationMatch[1];

// Extract customer WA number from table_15
// Format: *WA:* 2348XXXXXXXXX
const waMatch = replyToText.match(/WA:\*?\s*(\d+)/i);
if (!waMatch) return [];

const waNumber = waMatch[1];

// Extract customer code
const codeMatch = replyToText.match(/Code:\*?\s*(DPT-\d+)/i);
const customerCode = codeMatch ? codeMatch[1] : '';

return [{ json: {
  escalation_id: escalationId,
  admin_reply:   adminText,
  wa_number:     waNumber,
  customer_code: customerCode,
  admin_chat_id: adminChatId
} }];

const msgStats    = $('Get Message Stats').first().json;
const newCusts    = $('Get New Customers').first().json;
const totalCusts  = $('Get Total Customers').first().json;

const today = new Date().toLocaleDateString('en-GB', {
  timeZone: 'Africa/Lagos',
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

const report = [
  `📊 <b>Favour Daily Report</b>`,
  `📅 ${today}`,
  ``,
  `👥 <b>Customers</b>`,
  `• Total unique customers (all-time): ${totalCusts.total_customers_alltime || 0}`,
  `• Active today: ${msgStats.active_customers || 0}`,
  `• New today: ${newCusts.new_customers_today || 0}`,
  ``,
  `💬 <b>Message Breakdown</b>`,
  `• Code Redeemed: ${msgStats.positive_sentiments || 0}`,
  `• Other messages (queries, complaints etc): ${msgStats.other_messages || 0}`,
].filter(line => line !== '').join('\n');

return [{ json: {
  report,
  stat_date:           new Date().toISOString().split('T')[0],
  unique_customers:    parseInt(totalCusts.total_customers_alltime || 0),
  active_customers:    parseInt(msgStats.active_customers || 0),
  new_customers:       parseInt(newCusts.new_customers_today || 0),
  positive_sentiments: parseInt(msgStats.positive_sentiments || 0)
} }];

